def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value: a datetime.timedelta instance
    :type value: datetime.timedelta
    :return: total seconds as float
    :rtype: float
    """
    if value is None:
        raise TypeError("value must be a datetime.timedelta instance")
    try:
        return value.total_seconds()
    except AttributeError:
        # Fallback for older Python versions that lack total_seconds()
        try:
            return value.days * 86400 + value.seconds + value.microseconds / 1e6
        except Exception:
            raise TypeError("value must be a datetime.timedelta instance") from None

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    # Allow None to be passed through unchanged
    if value is None:
        return None

    # Dynamically import datetime to avoid top-level imports
    try:
        datetime_module = __import__('datetime')
    except ImportError as exc:
        raise TypeError("datetime module is required for dehydrate_time") from exc

    # Ensure the value is a datetime.time instance
    if not isinstance(value, datetime_module.time):
        raise TypeError(f"Expected a datetime.time instance, got {type(value).__name__}")

    # Convert the time to an ISO 8601 string representation
    return value.isoformat()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: dict with keys 'x' and 'y' representing the point coordinates
    """
    # Helper to validate coordinate values
    def _validate_coord(coord):
        if not isinstance(coord, (int, float)):
            raise ValueError(f"Coordinate value {coord!r} is not a number")
        return coord

    try:
        # Case 1: object with x and y attributes
        if hasattr(value, "x") and hasattr(value, "y"):
            x = _validate_coord(value.x)
            y = _validate_coord(value.y)
            return {"x": x, "y": y}

        # Case 2: tuple or list of length 2
        if isinstance(value, (tuple, list)) and len(value) == 2:
            x = _validate_coord(value[0])
            y = _validate_coord(value[1])
            return {"x": x, "y": y}

        # Case 3: dict with 'x' and 'y' keys
        if isinstance(value, dict) and "x" in value and "y" in value:
            x = _validate_coord(value["x"])
            y = _validate_coord(value["y"])
            return {"x": x, "y": y}

        raise TypeError(f"Unsupported type for point dehydration: {type(value).__name__}")

    except Exception as exc:
        # Re-raise with a more informative message
        raise ValueError(f"Failed to dehydrate point: {exc}") from exc

def keys(self):
        """ Return the keys of the record.

        :return: list of key names
        """
        try:
            # If the instance itself behaves like a dict (including subclasses)
            if isinstance(self, dict):
                # Use dict's keys method directly to avoid recursion
                return list(dict.keys(self))

            # If the instance has a 'data' attribute that is dict-like
            if hasattr(self, 'data') and isinstance(self.data, dict):
                return list(self.data.keys())

            # If the instance has a 'fields' attribute that is dict-like
            if hasattr(self, 'fields') and isinstance(self.fields, dict):
                return list(self.fields.keys())

            # If the instance provides a method to convert to dict
            if hasattr(self, 'to_dict') and callable(self.to_dict):
                return list(self.to_dict().keys())

            # Fallback: return public attributes from __dict__
            return [k for k in self.__dict__ if not k.startswith('_')]

        except Exception as exc:
            raise RuntimeError(f"Failed to retrieve keys: {exc}") from exc

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple or None")
    try:
        handlers = getattr(cls, "_protocol_handlers", {})
        if not isinstance(handlers, dict):
            raise RuntimeError("Protocol handlers mapping is not a dictionary")
        if protocol_version is None:
            return dict(handlers)
        return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve protocol handlers: {exc}") from exc

def values(self, *keys):
        """ Return the values of the record, optionally filtering to
        include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        try:
            data = self._data
        except AttributeError:
            raise AttributeError("The object does not have a '_data' attribute")

        # Ensure data behaves like an ordered mapping
        try:
            items = list(data.items())
        except AttributeError:
            raise TypeError("The '_data' attribute must support .items()")

        if not keys:
            return [value for _, value in items]

        result = []
        for key in keys:
            if isinstance(key, int):
                # Treat as index
                if key < 0 or key >= len(items):
                    raise IndexError(f"Index {key} out of range for values")
                result.append(items[key][1])
            else:
                # Treat as key lookup
                try:
                    result.append(data[key])
                except KeyError:
                    raise KeyError(f"Key {key!r} not found in values")
                except TypeError:
                    # key is unhashable
                    raise KeyError(f"Unhashable key {key!r} used for values")
        return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Retrieve the record's keys and values
    try:
        keys_list = self._keys
        values_list = self._values
    except AttributeError:
        raise AttributeError("Record object must have _keys and _values attributes")
    if len(keys_list) != len(values_list):
        raise ValueError("Record keys and values length mismatch")
    # If no specific keys are requested, return all
    if not keys:
        return dict(zip(keys_list, values_list))
    result = {}
    for key in keys:
        if isinstance(key, int):
            # Index-based access
            try:
                key_name = keys_list[key]
                value = values_list[key]
            except IndexError:
                raise IndexError(f"Index {key} out of bounds")
            result[key_name] = value
        elif isinstance(key, str):
            # Key-based access
            if key in keys_list:
                idx = keys_list.index(key)
                result[key] = values_list[idx]
            else:
                result[key] = None
        else:
            raise TypeError(f"Key {key!r} must be an int or str")
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Validate n
    if not isinstance(n, int):
        raise TypeError(f"n must be an integer, got {type(n).__name__}")
    if n < -1:
        raise ValueError(f"n must be >= -1, got {n}")

    # Validate qid
    if not isinstance(qid, int):
        raise TypeError(f"qid must be an integer, got {type(qid).__name__}")
    if qid < -1:
        raise ValueError(f"qid must be >= -1, got {qid}")

    # Validate dehydration_hooks
    if dehydration_hooks is not None:
        if not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dict")
        for key, func in dehydration_hooks.items():
            if not isinstance(key, type):
                raise TypeError(f"dehydration_hooks key {key!r} is not a type")
            if not callable(func):
                raise TypeError(f"dehydration_hooks value for {key!r} is not callable")
    else:
        dehydration_hooks = {}

    # Validate hydration_hooks
    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dict")
        for key, func in hydration_hooks.items():
            if not isinstance(key, type):
                raise TypeError(f"hydration_hooks key {key!r} is not a type")
            if not callable(func):
                raise TypeError(f"hydration_hooks value for {key!r} is not callable")
    else:
        hydration_hooks = {}

    # Append DISCARD message to output queue
    try:
        self._output_queue.append(("DISCARD", n, qid))
    except AttributeError as exc:
        raise RuntimeError("Output queue not available") from exc

    # Return a Response object
    return Response(self, handlers=handlers,
                    dehydration_hooks=dehydration_hooks,
                    hydration_hooks=hydration_hooks)

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    if mode is not None and mode not in ("READ", "WRITE"):
        raise ValueError("mode must be 'READ' or 'WRITE'")

    # Validate bookmarks
    if bookmarks is not None:
        try:
            iter(bookmarks)
        except TypeError:
            raise TypeError("bookmarks must be an iterable")

    # Validate metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dictionary")

    # Validate timeout
    if timeout is not None and not isinstance(timeout, (int, float)):
        raise TypeError("timeout must be a number")

    # Validate db
    if db is not None and not isinstance(db, str):
        raise TypeError("db must be a string")

    # Validate imp_user
    if imp_user is not None and not isinstance(imp_user, str):
        raise TypeError("imp_user must be a string")

    # Validate dehydration_hooks
    if dehydration_hooks is not None:
        if not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dict")
        for key, func in dehydration_hooks.items():
            if not isinstance(key, type):
                raise TypeError("dehydration_hooks keys must be types")
            if not callable(func):
                raise TypeError("dehydration_hooks values must be callables")

    # Validate hydration_hooks
    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dict")
        for key, func in hydration_hooks.items():
            if not isinstance(key, type):
                raise TypeError("hydration_hooks keys must be types")
            if not callable(func):
                raise TypeError("hydration_hooks values must be callables")

    # Build parameters dictionary
    params = {}
    if mode is not None:
        params["mode"] = mode
    if bookmarks is not None:
        params["bookmarks"] = list(bookmarks)
    if metadata is not None:
        params["metadata"] = metadata
    if timeout is not None:
        params["timeout"] = timeout
    if db is not None:
        params["db"] = db
    if imp_user is not None:
        params["imp_user"] = imp_user

    # Store hooks if provided (assuming the connection has these attributes)
    if dehydration_hooks is not None:
        self._dehydration_hooks = dehydration_hooks
    if hydration_hooks is not None:
        self._hydration_hooks = hydration_hooks

    # Append the BEGIN message to the output queue (assuming a queue attribute)
    if hasattr(self, "_queue"):
        self._queue.append(("BEGIN", params))
    else:
        # If no queue attribute exists, raise an informative error
        raise AttributeError("The connection object does not have a '_queue' attribute")

    # Return a simple Response-like object (dictionary) for demonstration purposes
    return {"type": "BEGIN", "params": params, "handlers": handlers}

def round_half_to_even(n):
    """
    Round a number to the nearest integer using the "round half to even" rule.
    This is equivalent to Python's built-in round() for numeric types.
    """
    if not isinstance(n, (int, float)):
        raise TypeError("n must be an int or float")
    return int(round(n))

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate the class name
    if not isinstance(name, str):
        raise TypeError("name must be a string")

    # Validate fields
    if isinstance(fields, dict):
        field_names = list(fields.keys())
    elif isinstance(fields, (list, tuple)):
        field_names = list(fields)
    else:
        raise TypeError("fields must be a dict or a list/tuple of field names")

    # Ensure all field names are strings
    for f in field_names:
        if not isinstance(f, str):
            raise TypeError(f"field name {f!r} is not a string")

    # Validate srid_map
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")
    for key, value in srid_map.items():
        if not isinstance(key, str):
            raise TypeError(f"SRID map key {key!r} is not a string")
        if not isinstance(value, int):
            raise TypeError(f"SRID map value for {key!r} is not an int")

    # Build the class dictionary
    class_dict = {"SRID_MAP": srid_map}

    # Add default values as class attributes if fields is a dict
    if isinstance(fields, dict):
        for key, default in fields.items():
            class_dict[key] = default

    # Define the __init__ method
    def __init__(self, *args, **kwargs):
        # Call the base class __init__
        try:
            super(Point, self).__init__(*args, **kwargs)
        except NameError as e:
            raise RuntimeError("Base class Point is not defined") from e

        # Set instance attributes for each field
        for field in field_names:
            if field in kwargs:
                setattr(self, field, kwargs[field])
            else:
                # Use the class attribute default if present, otherwise None
                if hasattr(self.__class__, field):
                    setattr(self, field, getattr(self.__class__, field))
                else:
                    setattr(self, field, None)

    class_dict["__init__"] = __init__

    # Create the new subclass
    try:
        new_cls = type(name, (Point,), class_dict)
    except Exception as e:
        raise RuntimeError(f"Failed to create class {name}") from e

    return new_cls

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    if not isinstance(message, str):
        raise TypeError("deprecation message must be a string")
    import warnings
    import functools

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    try:
        items = list(seq)
    except Exception as e:
        raise TypeError("seq must be an iterable of strings") from e
    if not all(isinstance(x, str) for x in items):
        raise TypeError("All elements of seq must be strings")
    m = 2**32
    a = 1664525
    c = 1013904223
    seed = 0
    for s in items:
        for ch in s:
            seed = (seed * 31 + ord(ch)) % m
    n = len(items)
    for i in range(n - 1, 0, -1):
        seed = (a * seed + c) % m
        j = seed % (i + 1)
        items[i], items[j] = items[j], items[i]
    return items

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    def decorator(func):
        cache = {}
        counts = {}

        def wrapper(*args, **kwargs):
            # Build cache key
            try:
                if typed:
                    key = (
                        args,
                        tuple(sorted(kwargs.items())),
                        tuple(type(arg) for arg in args),
                        tuple(type(v) for v in kwargs.values()),
                    )
                else:
                    key = (args, tuple(sorted(kwargs.items())))
                # Ensure key is hashable
                hash(key)
            except Exception:
                # Unhashable arguments; bypass cache
                return func(*args, **kwargs)

            if key in cache:
                counts[key] += 1
                return cache[key]

            # Compute result
            try:
                result = func(*args, **kwargs)
            except Exception:
                raise

            # Store in cache
            cache[key] = result
            counts[key] = 1

            # Evict if necessary
            if len(cache) > maxsize:
                # Find the least frequently used key(s)
                min_count = min(counts.values())
                # Evict the first key with the minimum count
                for evict_key in list(counts):
                    if counts[evict_key] == min_count:
                        del cache[evict_key]
                        del counts[evict_key]
                        break

            return result

        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__module__ = func.__module__
        wrapper.__defaults__ = func.__defaults__
        wrapper.__kwdefaults__ = func.__kwdefaults__
        wrapper.__annotations__ = getattr(func, "__annotations__", {})
        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    # Attempt to get the first key in insertion order
    try:
        first_key = next(iter(self))
    except StopIteration:
        raise KeyError('popitem(): dictionary is empty')
    # Retrieve the associated value
    try:
        value = self[first_key]
    except KeyError:
        # This should not happen, but guard against it
        raise KeyError(f'popitem(): key {first_key!r} not found')
    # Remove the key from the mapping
    try:
        del self[first_key]
    except Exception as exc:
        raise RuntimeError(f'popitem(): failed to delete key {first_key!r}') from exc
    return (first_key, value)

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    # Attempt to retrieve the value if the key exists
    try:
        if key in self:
            return self[key]
    except Exception as exc:
        # If the key is not hashable or another error occurs, re-raise with context
        raise type(exc)(f"Error accessing key {key!r}: {exc}") from exc

    # Key is not present; set it to the default value
    try:
        self[key] = default
    except Exception as exc:
        # If setting the key fails (e.g., key not hashable), re-raise with context
        raise type(exc)(f"Error setting key {key!r} to {default!r}: {exc}") from exc

    return default

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default
    except TypeError as e:
        raise TypeError(f"Key {key!r} is not hashable: {e}") from e
    except Exception as e:
        raise RuntimeError(f"Error accessing key {key!r}: {e}") from e

@staticmethod
    def file_to_textbuffer(file_name, encoding):
        """
        Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
        CAUTION : This will read the whole file IN MEMORY.
        :param file_name: File name.
        :type file_name: str
        :param encoding: Encoding to use.
        :type encoding: str
        :return: A text buffer or None in case of error.
        :rtype str
        """
        # Validate input types
        if not isinstance(file_name, str) or not isinstance(encoding, str):
            return None
        try:
            with open(file_name, 'r', encoding=encoding) as f:
                return f.read()
        except Exception:
            return None

@staticmethod
def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    # Validate input
    if not isinstance(file_name, str) or not file_name:
        return False
    try:
        # Use os.path.exists to check file existence
        import os
        return os.path.isfile(file_name)
    except Exception:
        # Any error (e.g., permission, invalid path) results in False
        return False

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    try:
        name = self.__class__.__name__
    except Exception as exc:
        raise RuntimeError("Unable to determine class name") from exc
    for suffix in ("Py", "Fallback"):
        if name.endswith(suffix):
            return name[:-len(suffix)]
    return name

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("all must be a boolean")
    cls = self.__class__
    attrs = set()

    def _collect(c):
        # Collect attributes from the class dictionary
        for name, value in c.__dict__.items():
            if name.startswith("_"):
                continue
            if callable(value):
                continue
            attrs.add(name)
        # Collect annotated attributes (may not have a value in __dict__)
        annotations = getattr(c, "__annotations__", {})
        for name in annotations:
            if name.startswith("_"):
                continue
            attrs.add(name)

    if all:
        for base in cls.__mro__:
            _collect(base)
    else:
        _collect(cls)

    return sorted(attrs)

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    else:
        if not isinstance(output, list):
            raise TypeError("output must be a list")
    if sequence is None:
        return output
    # Treat string/bytes as a single item, not iterable
    if isinstance(sequence, (str, bytes)):
        output.append(sequence)
        return output
    # Try to iterate over the sequence
    try:
        iter(sequence)
    except TypeError:
        output.append(sequence)
        return output
    for item in sequence:
        if isinstance(item, (str, bytes)):
            output.append(item)
        elif isinstance(item, (list, tuple)):
            for sub in item:
                output.append(sub)
        else:
            output.append(item)
    return output

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    Returns True if C optimizations are ignored, False otherwise.
    """
    try:
        # Assume `_c_optimizations_required` is defined elsewhere and returns a boolean.
        return not _c_optimizations_required()
    except NameError as e:
        raise NameError("Function `_c_optimizations_required` is not defined") from e
    except Exception as e:
        raise RuntimeError("Error determining C optimizations status") from e

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the context
        try:
            self._context = {}
        except AttributeError:
            # If the attribute does not exist, create it
            self._context = {}

        # Reinitialize bins
        # Determine whether we should use the initial value or a factory
        has_initial = hasattr(self, "_initial_value") and self._initial_value is not None
        has_factory = hasattr(self, "_make_bins") and callable(self._make_bins)

        if has_initial:
            # Ensure bins exist and are a dict
            if not hasattr(self, "_bins") or not isinstance(self._bins, dict):
                raise TypeError("Histogram bins must be a dict to reset with an initial value.")
            # Reset each bin to the initial value
            for key in self._bins:
                self._bins[key] = self._initial_value
        elif has_factory:
            # Use the factory to create new bins
            new_bins = self._make_bins()
            if new_bins is None:
                raise TypeError("make_bins() returned None; expected a dict.")
            if not isinstance(new_bins, dict):
                raise TypeError("make_bins() must return a dict of bins.")
            self._bins = new_bins
        else:
            # Neither an initial value nor a factory is available
            raise ValueError("Cannot reset histogram: no initial value or make_bins() defined.")

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Validate separator
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    # Validate header
    if header is not None and not isinstance(header, str):
        raise TypeError("header must be a string or None")
    lines = []
    if header is not None:
        lines.append(header)
    # Iterate over points
    try:
        for point in self:
            # Determine coordinate and value
            if isinstance(point, dict):
                if "coord" not in point or "value" not in point:
                    raise ValueError("Point dict must contain 'coord' and 'value' keys")
                coord = point["coord"]
                value = point["value"]
            elif isinstance(point, (list, tuple)):
                if len(point) == 2:
                    coord, value = point
                elif len(point) > 2:
                    coord = point[0]
                    value = point[1:]
                else:
                    raise ValueError("Point tuple/list must have at least two elements")
            else:
                # Try attribute access
                try:
                    coord = point.coord
                    value = point.value
                except AttributeError:
                    raise ValueError("Point must be a tuple/list/dict or have .coord and .value attributes")
            # Convert coordinate to string
            if isinstance(coord, (list, tuple)):
                coord_str = separator.join(map(str, coord))
            else:
                coord_str = str(coord)
            # Convert value to string
            if isinstance(value, (list, tuple)):
                value_str = separator.join(map(str, value))
            else:
                value_str = str(value)
            lines.append(coord_str + separator + value_str)
    except Exception as exc:
        raise RuntimeError(f"Error converting graph to CSV: {exc}") from exc
    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate the coordinate name
    if not isinstance(coord_name, str):
        raise TypeError(f"coord_name must be a string, got {type(coord_name).__name__}")

    # Ensure the error indices attribute exists
    if not hasattr(self, "_err_indices"):
        raise AttributeError("The object does not have an '_err_indices' attribute")

    err_indices = self._err_indices

    # Determine how error indices are stored
    if isinstance(err_indices, dict):
        # Mapping from coordinate name to indices
        if coord_name not in err_indices:
            raise ValueError(f"Coordinate '{coord_name}' not found in error indices mapping")
        indices = err_indices[coord_name]
    elif isinstance(err_indices, (list, tuple)):
        # List/tuple of indices; need coordinate order
        if not hasattr(self, "_coord_names"):
            raise AttributeError("The object does not have a '_coord_names' attribute required for list-based indices")
        try:
            idx = self._coord_names.index(coord_name)
        except ValueError:
            raise ValueError(f"Coordinate '{coord_name}' not found in coordinate names")
        indices = err_indices[idx]
    else:
        raise TypeError(f"_err_indices must be a dict or list/tuple, got {type(err_indices).__name__}")

    # Validate the retrieved indices
    if indices is None:
        raise ValueError(f"No error indices defined for coordinate '{coord_name}'")

    # Ensure the indices are iterable and return a copy
    try:
        return list(indices)
    except TypeError:
        raise TypeError(f"Error indices for coordinate '{coord_name}' are not iterable")

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate that inputs are not None
    if bins is None or edges is None:
        raise TypeError("bins and edges must not be None")

    # Convert to lists to allow multiple passes
    try:
        bins_list = list(bins)
    except TypeError:
        raise TypeError("bins must be an iterable")
    try:
        edges_list = list(edges)
    except TypeError:
        raise TypeError("edges must be an iterable")

    # Empty bins: integral is zero (no data)
    if len(bins_list) == 0:
        return 0.0

    # edges must contain at least two values
    if len(edges_list) < 2:
        raise ValueError("edges must contain at least two values")

    # Number of bins must be one less than number of edges
    if len(bins_list) != len(edges_list) - 1:
        raise ValueError("Number of bins must be one less than number of edges")

    # Ensure all bin values are numeric
    for i, val in enumerate(bins_list):
        try:
            float(val)
        except Exception:
            raise TypeError(f"bins[{i}] is not numeric")

    # Ensure all edge values are numeric
    for i, val in enumerate(edges_list):
        try:
            float(val)
        except Exception:
            raise TypeError(f"edges[{i}] is not numeric")

    # Ensure edges are strictly increasing
    for i in range(len(edges_list) - 1):
        if edges_list[i + 1] <= edges_list[i]:
            raise ValueError("edges must be strictly increasing")

    # Compute the integral as sum of bin value times bin width
    total = 0.0
    for bin_val, left, right in zip(bins_list, edges_list, edges_list[1:]):
        width = right - left
        total += float(bin_val) * width

    return total

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # If seq is a Source sequence, it is not a valid FillRequestSeq
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        # Source class not defined; assume seq is not a Source
        pass

    # If seq itself is a FillRequest, it's valid
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # FillRequest class not defined; cannot be a FillRequest
        pass

    # Otherwise, try to iterate over seq and look for any FillRequest element
    try:
        for item in seq:
            try:
                if isinstance(item, FillRequest):
                    return True
            except NameError:
                # If FillRequest is not defined, skip checking
                continue
    except TypeError:
        # seq is not iterable
        return False

    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run', None))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'compute', None))
    except Exception:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("d1 and d2 must be dictionaries")
    if not isinstance(level, int):
        raise TypeError("level must be an integer")
    if level < -1:
        raise ValueError("level must be -1 or a non-negative integer")

    def _diff(sub_d1, sub_d2, cur_level):
        result = {}
        for key, val in sub_d1.items():
            if key not in sub_d2:
                result[key] = val
            else:
                val2 = sub_d2[key]
                if isinstance(val, dict) and isinstance(val2, dict) and cur_level != 0:
                    # Recurse into nested dictionaries
                    if cur_level == -1:
                        nested = _diff(val, val2, cur_level)
                    else:
                        nested = _diff(val, val2, cur_level - 1)
                    if nested:
                        result[key] = nested
                else:
                    # Compare values; if different, include
                    if val != val2:
                        result[key] = val
        return result

    return _diff(d1, d2, level)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    # Assume LABEL_KEY_REGEX, LABEL_VALUE_REGEX and ValidationError are defined elsewhere
    errors = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): "expected string or bytes-like object"})
        else:
            # Validate key regex
            if not LABEL_KEY_REGEX.match(key):
                errors.append(
                    {key: f"Label key '{key}' does not match the regex [...]"}
                )

        # Validate value type
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): "expected string or bytes-like object"})
        else:
            # Validate value regex
            if not LABEL_VALUE_REGEX.match(value):
                errors.append(
                    {value: f"Label value '{value}' does not match the regex [...]"}
                )

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")
    if not isinstance(first_level, bool):
        raise TypeError("first_level must be a bool")

    # Fields that identify a Kubernetes resource
    identifying_fields = {"apiVersion", "kind", "metadata"}

    def _process_value(value, is_first_level):
        if isinstance(value, dict):
            return generate_default_observer_schema_dict(value, first_level=False)
        if isinstance(value, list):
            processed = []
            for item in value:
                if isinstance(item, dict):
                    processed.append(generate_default_observer_schema_dict(item, first_level=False))
                elif isinstance(item, list):
                    # Recursively process nested lists
                    processed.append(_process_value(item, first_level=False))
                else:
                    processed.append(None)
            return processed
        # Non-dict, non-list values are replaced with None
        return None

    result = {}
    for key, value in manifest_dict.items():
        if first_level and key in identifying_fields:
            # Copy identifying fields as-is
            result[key] = value
        else:
            result[key] = _process_value(value, first_level=False)
    return result

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from resource kind to its default observer schema. The default
        schema is represented by ``None`` which indicates that all fields of the
        resource should be observed.

    Raises:
        ValueError: If the provided ``app`` does not have the expected structure.
    """
    # Basic validation of the input
    if app is None:
        raise ValueError("app must not be None")

    # Ensure the app has a spec with a manifest
    try:
        manifest = app.spec.manifest
    except AttributeError as exc:
        raise ValueError("app must have a 'spec.manifest' attribute") from exc

    if not isinstance(manifest, list):
        raise ValueError("app.spec.manifest must be a list of resources")

    # Retrieve any custom observer schema that may already be defined
    custom_schema = getattr(app.spec, "observer_schema", {})
    if custom_schema is None:
        custom_schema = {}
    if not isinstance(custom_schema, dict):
        raise ValueError("app.spec.observer_schema must be a dict if present")

    # Build the default schema for resources that do not have a custom schema
    default_schema = {}
    for resource in manifest:
        if not isinstance(resource, dict):
            # Skip non-dict entries
            continue
        kind = resource.get("kind")
        if not kind:
            # Skip resources without a kind
            continue
        if kind not in custom_schema:
            # Use ``None`` to indicate that all fields should be observed
            default_schema[kind] = None

    return default_schema

def validate(self, path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Resolve the root path
        if path is None:
            return False
        # If path is a string, use it directly
        if isinstance(path, str):
            root = pathlib.Path(path)
        # If path has a 'path' attribute (e.g., a pyfs root), use that
        elif hasattr(path, "path"):
            root = pathlib.Path(path.path)
        else:
            # Fallback: convert to string
            root = pathlib.Path(str(path))

        if not root.is_dir():
            return False

        # Check for required OCFL files/directories
        ocfl_version_file = root / ".ocfl_version"
        ocfl_root_dir = root / ".ocfl_root"

        if not ocfl_version_file.is_file() or not ocfl_root_dir.is_dir():
            return False

        # Ensure at least one object directory exists inside .ocfl_root
        has_object = False
        for child in ocfl_root_dir.iterdir():
            if child.is_dir() and (child / ".ocfl_version").is_file():
                has_object = True
                break

        if not has_object:
            return False

        return True
    except Exception:
        # Any error during validation results in False
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    try:
        status = getattr(self, "status", None)
    except Exception as exc:
        raise RuntimeError("Unable to retrieve validator status") from exc
    if status is None:
        status_repr = ""
    else:
        try:
            status_repr = str(status)
        except Exception as exc:
            raise RuntimeError("Failed to convert status to string") from exc
    return f"{prefix}{status_repr}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    # Attempt to locate the log attribute
    log = None
    for attr in ('log', 'validation_log', 'messages'):
        if hasattr(self, attr):
            log = getattr(self, attr)
            break
    if log is None:
        return ''
    # Normalize log to an iterable of lines
    if isinstance(log, str):
        lines = [log]
    else:
        try:
            lines = list(log)
        except Exception:
            lines = [str(log)]
    # Prefix each line and join
    prefixed_lines = [prefix + str(line) for line in lines]
    return '\n'.join(prefixed_lines)

def validate(self, inventory, extract_spec_version=False):
        """
        Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Basic argument checks
        if not isinstance(inventory, dict):
            raise TypeError("inventory must be a dictionary")
        if not isinstance(extract_spec_version, bool):
            raise TypeError("extract_spec_version must be a boolean")

        # Determine the spec version to use
        spec_version = self.spec_version
        if extract_spec_version:
            type_val = inventory.get("type")
            if type_val == "inventory":
                spec_version = "1.0"
            elif type_val == "inventory_v2":
                spec_version = "2.0"
            # If type is missing or unrecognized, keep the default self.spec_version

        # Ensure the inventory contains a spec_version key
        if "spec_version" not in inventory:
            inventory["spec_version"] = spec_version

        # Validation logic based on spec_version
        try:
            if spec_version == "1.0":
                required_keys = ["type", "spec_version", "items"]
                for key in required_keys:
                    if key not in inventory:
                        raise ValueError(f"Missing required key '{key}' for spec_version 1.0")

                if not isinstance(inventory["items"], list):
                    raise ValueError("'items' must be a list")

                for idx, item in enumerate(inventory["items"]):
                    if not isinstance(item, dict):
                        raise ValueError(f"Item at index {idx} must be a dictionary")
                    if "id" not in item or "name" not in item:
                        raise ValueError(f"Item at index {idx} must contain 'id' and 'name'")

            elif spec_version == "2.0":
                required_keys = ["type", "spec_version", "entries"]
                for key in required_keys:
                    if key not in inventory:
                        raise ValueError(f"Missing required key '{key}' for spec_version 2.0")

                if not isinstance(inventory["entries"], list):
                    raise ValueError("'entries' must be a list")

                for idx, entry in enumerate(inventory["entries"]):
                    if not isinstance(entry, dict):
                        raise ValueError(f"Entry at index {idx} must be a dictionary")
                    if "identifier" not in entry or "description" not in entry:
                        raise ValueError(f"Entry at index {idx} must contain 'identifier' and 'description'")

            else:
                raise ValueError(f"Unsupported spec_version '{spec_version}'")

        except Exception as exc:
            # Wrap any unexpected exception in a RuntimeError for clarity
            raise RuntimeError(f"Inventory validation failed: {exc}") from exc

        return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type check
    if prior is None:
        raise TypeError("prior must not be None")
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an instance of the same class as self")

    # Ensure required attributes exist
    required_attrs = ('inventory', 'version', 'id')
    for attr in required_attrs:
        if not hasattr(self, attr):
            raise AttributeError(f"self is missing required attribute '{attr}'")
        if not hasattr(prior, attr):
            raise AttributeError(f"prior is missing required attribute '{attr}'")

    # Check that the inventory IDs match
    if self.id != prior.id:
        raise ValueError(f"Inventory IDs do not match: self.id={self.id} != prior.id={prior.id}")

    # Check that the current version is greater than the prior version
    try:
        if self.version <= prior.version:
            raise ValueError(f"Current inventory version ({self.version}) must be greater than prior version ({prior.version})")
    except TypeError:
        # Fallback to string comparison if versions are not directly comparable
        if str(self.version) <= str(prior.version):
            raise ValueError(f"Current inventory version ({self.version}) must be greater than prior version ({prior.version})")

    # Optional: verify that prior inventory is a subset of current inventory
    try:
        # Handle dict inventories
        if isinstance(self.inventory, dict) and isinstance(prior.inventory, dict):
            if not set(prior.inventory.keys()).issubset(set(self.inventory.keys())):
                raise ValueError("Prior inventory keys are not a subset of current inventory keys")
        # Handle list inventories
        elif isinstance(self.inventory, list) and isinstance(prior.inventory, list):
            if not set(prior.inventory).issubset(set(self.inventory)):
                raise ValueError("Prior inventory items are not a subset of current inventory items")
        # Handle other iterable types generically
        elif hasattr(self.inventory, '__contains__') and hasattr(prior.inventory, '__iter__'):
            for item in prior.inventory:
                if item not in self.inventory:
                    raise ValueError("Prior inventory contains items not present in current inventory")
    except Exception as exc:
        # Wrap any unexpected errors in a ValueError for consistency
        raise ValueError(f"Error while validating inventory subset: {exc}") from exc

    # If all checks pass, return True
    return True

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inventory
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict mapping versions to data")
    if version not in inventory:
        raise KeyError(f"version {version!r} not found in inventory")
    version_data = inventory[version]

    # Prepare the result mapping
    logical_path_map = {}

    # Helper to add a mapping entry
    def _add_entry(logical_path, content_file):
        if logical_path is None or content_file is None:
            return
        logical_path_map.setdefault(logical_path, set()).add(content_file)

    # Determine the structure of version_data
    if isinstance(version_data, dict):
        # Common pattern: {'files': {...}} or directly mapping logical_path -> content_file
        files_section = version_data.get("files", version_data)
        if isinstance(files_section, dict):
            for lp, cf in files_section.items():
                _add_entry(lp, cf)
        elif isinstance(files_section, list):
            for entry in files_section:
                if isinstance(entry, dict):
                    _add_entry(entry.get("logical_path"), entry.get("content_file"))
                elif isinstance(entry, (list, tuple)) and len(entry) >= 2:
                    _add_entry(entry[0], entry[1])
                else:
                    # Unsupported entry format; skip
                    continue
        else:
            raise ValueError("Unsupported 'files' section format in inventory")
    elif isinstance(version_data, list):
        # Direct list of entries
        for entry in version_data:
            if isinstance(entry, dict):
                _add_entry(entry.get("logical_path"), entry.get("content_file"))
            elif isinstance(entry, (list, tuple)) and len(entry) >= 2:
                _add_entry(entry[0], entry[1])
            else:
                continue
    else:
        raise TypeError("Unsupported version data type in inventory")

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")
    if 'files' not in fixity:
        raise ValueError("Fixity block missing required 'files' key.")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' must be a list.")
    if not files:
        raise ValueError("'files' list cannot be empty.")

    # Convert manifest to a set of valid paths
    try:
        manifest_set = set()
        for f in manifest_files:
            if not isinstance(f, str):
                raise ValueError("All entries in manifest_files must be strings.")
            manifest_set.add(f)
    except TypeError:
        raise ValueError("manifest_files must be an iterable of strings.")

    seen_paths = set()
    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each entry in 'files' must be a dictionary.")
        if 'path' not in entry:
            raise ValueError("Each file entry must contain a 'path' key.")
        path = entry['path']
        if not isinstance(path, str):
            raise ValueError("File 'path' must be a string.")
        if path in seen_paths:
            raise ValueError(f"Duplicate file path in fixity block: {path}")
        seen_paths.add(path)

        if path not in manifest_set:
            raise ValueError(f"File path '{path}' in fixity block not found in manifest.")

        # Optional: check for hash and size fields
        if 'hash' not in entry:
            raise ValueError(f"File entry for '{path}' missing 'hash' key.")
        if 'size' not in entry:
            raise ValueError(f"File entry for '{path}' missing 'size' key.")
        if not isinstance(entry['hash'], str):
            raise ValueError(f"Hash for '{path}' must be a string.")
        if not isinstance(entry['size'], (int, float)):
            raise ValueError(f"Size for '{path}' must be numeric.")

    # If all checks pass, return True (or None)
    return True

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")
    if not os.path.isdir(path):
        raise NotADirectoryError(f"Path is not a directory: {path}")
    try:
        entries = os.listdir(path)
    except OSError as e:
        raise e
    files = [f for f in entries if os.path.isfile(os.path.join(path, f))]
    return files

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        A dictionary where each key is the basename of an XML file (without extension)
        and each value is another dictionary mapping the relative file path within the
        zip to its content as bytes.
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError(f"zip_path must be a string, got {type(zip_path).__name__}")

    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    try:
        z = zipfile.ZipFile(zip_path, 'r')
    except zipfile.BadZipFile as exc:
        raise zipfile.BadZipFile(f"Invalid zip file: {zip_path}") from exc

    # First pass: collect basenames of all XML files
    xml_basenames = set()
    for info in z.infolist():
        if info.is_dir():
            continue
        if info.filename.lower().endswith('.xml'):
            base = os.path.splitext(os.path.basename(info.filename))[0]
            xml_basenames.add(base)

    # Second pass: group files by those basenames
    result = {}
    for info in z.infolist():
        if info.is_dir():
            continue
        base = os.path.splitext(os.path.basename(info.filename))[0]
        if base in xml_basenames:
            if base not in result:
                result[base] = {}
            try:
                content = z.read(info)
            except Exception as exc:
                # If reading a file fails, skip it but log the error
                raise IOError(f"Failed to read {info.filename} from zip") from exc
            result[base][info.filename] = content

    z.close()
    return result

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`.
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None:
        raise ValueError("node cannot be None")
    if not isinstance(pubdate_xpaths, (list, tuple)):
        raise TypeError("pubdate_xpaths must be a list or tuple")
    for xpath in pubdate_xpaths:
        try:
            result = node.xpath(xpath)
        except Exception:
            continue
        if result:
            first = result[0]
            if isinstance(first, str):
                return first
            else:
                return first.text
    return None

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper functions
    def is_op(expr, op):
        return isinstance(expr, tuple) and expr and expr[0] == op

    def contains(expr, sub):
        """Return True if sub is equal to expr or is contained within expr."""
        if expr == sub:
            return True
        if isinstance(expr, tuple):
            return any(contains(arg, sub) for arg in expr[1:])
        return False

    def apply_absorption(expr):
        """Apply absorption rules to a single expression recursively."""
        if not isinstance(expr, tuple):
            return expr
        op = expr[0]
        if op == '~':
            operand = apply_absorption(expr[1])
            return ('~', operand)
        if op in ('&', '|'):
            left = apply_absorption(expr[1])
            right = apply_absorption(expr[2])

            # Absorption
            if op == '&':
                # A & (A | B) => A
                if is_op(right, '|') and left in right[1:]:
                    return left
                if is_op(left, '|') and right in left[1:]:
                    return right
                # Negative absorption: A & (~A | B) => A & B
                if is_op(right, '|'):
                    for sub in right[1:]:
                        if is_op(sub, '~') and sub[1] == left:
                            other = [s for s in right[1:] if s != sub]
                            if other:
                                return ('&', left, other[0])
                if is_op(left, '|'):
                    for sub in left[1:]:
                        if is_op(sub, '~') and sub[1] == right:
                            other = [s for s in left[1:] if s != sub]
                            if other:
                                return ('&', right, other[0])
            elif op == '|':
                # A | (A & B) => A
                if is_op(right, '&') and left in right[1:]:
                    return left
                if is_op(left, '&') and right in left[1:]:
                    return right
                # Negative absorption: A | (~A & B) => A | B
                if is_op(right, '&'):
                    for sub in right[1:]:
                        if is_op(sub, '~') and sub[1] == left:
                            other = [s for s in right[1:] if s != sub]
                            if other:
                                return ('|', left, other[0])
                if is_op(left, '&'):
                    for sub in left[1:]:
                        if is_op(sub, '~') and sub[1] == right:
                            other = [s for s in left[1:] if s != sub]
                            if other:
                                return ('|', right, other[0])

            # No absorption applied; return simplified expression
            return (op, left, right)
        # Unknown operator; return as is
        return expr

    # Validate args
    try:
        iterator = iter(args)
    except TypeError:
        raise TypeError("args must be an iterable of expressions")

    # Simplify each expression
    result = []
    for expr in args:
        try:
            simplified = apply_absorption(expr)
            result.append(simplified)
        except Exception as e:
            # If an error occurs during simplification, propagate it
            raise ValueError(f"Error simplifying expression {expr!r}: {e}") from e

    return result

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    if hook is None:
        raise ValueError("hook cannot be None")
    def decorator(func):
        if not callable(func):
            raise TypeError("listener must be callable")
        if not hasattr(self, 'registry'):
            self.registry = {}
        registry = self.registry
        if not isinstance(registry, dict):
            raise TypeError("registry must be a dict")
        listeners = registry.setdefault(hook, [])
        if func not in listeners:
            listeners.append(func)
        return func
    return decorator

def tzname_in_python2(namefunc):
    import sys
    if sys.version_info[0] < 3:
        def wrapper(*args, **kwargs):
            result = namefunc(*args, **kwargs)
            if isinstance(result, unicode):
                return result.encode('utf-8')
            return result
        return wrapper
    else:
        return namefunc

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Try to get the version of the current package using importlib.metadata
        import importlib.metadata
        pkg_name = __package__ or __name__
        version = importlib.metadata.version(pkg_name)
        return {"version": version}
    except Exception:
        # Fallback to a default version if any error occurs
        return {"version": "0.0.0"}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate pieces
    if not hasattr(pieces, "__iter__") or isinstance(pieces, (str, bytes)):
        raise TypeError("pieces must be an iterable of strings or integers")
    try:
        str_pieces = [str(p) for p in pieces]
    except Exception as exc:
        raise TypeError("all elements of pieces must be convertible to string") from exc

    # Validate style
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    style = style.lower()

    # Define supported styles and their separators
    separators = {
        "dot": ".",
        "dash": "-",
        "underscore": "_",
        "none": "",
        "semver": ".",   # simple dot-separated for semver
        "pep440": ".",   # simple dot-separated for PEP 440
    }

    if style not in separators:
        raise ValueError(
            f"Unsupported style '{style}'. Supported styles: {', '.join(separators)}"
        )

    sep = separators[style]
    return sep.join(str_pieces)

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    # Validate that pieces is an iterable
    try:
        iterator = iter(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable")

    # Determine if a '+' already exists in any element
    try:
        has_plus = any('+' in str(item) for item in iterator)
    except Exception as e:
        raise ValueError(f"Error processing pieces: {e}")

    return '.' if has_plus else '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os
    import shlex

    # Prepare the command list
    if isinstance(commands, str):
        cmd_list = shlex.split(commands)
    else:
        cmd_list = list(commands)

    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of arguments")

    full_cmd = cmd_list + list(args)

    # Merge environment
    env_dict = os.environ.copy()
    if env:
        if not isinstance(env, dict):
            raise TypeError("env must be a dictionary")
        env_dict.update(env)

    # Verbose output
    if verbose:
        print("Running command:", " ".join(shlex.quote(part) for part in full_cmd))

    # Set stderr handling
    stderr_option = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env_dict,
            capture_output=True,
            text=True,
            stderr=stderr_option,
        )
    except FileNotFoundError as e:
        raise FileNotFoundError(f"Command not found: {full_cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Error running command: {full_cmd}") from e

    if result.returncode != 0:
        raise subprocess.CalledProcessError(
            returncode=result.returncode,
            cmd=full_cmd,
            output=result.stdout,
            stderr=result.stderr,
        )

    return result.stdout.strip()

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate argument types
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a bool")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a bool")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a bool")

    # Determine the root directory to validate
    root = getattr(self, "root", None) or getattr(self, "storage_root", None)
    if root is None:
        raise AttributeError("Instance has no 'root' or 'storage_root' attribute")
    if not os.path.isdir(root):
        raise ValueError(f"Root path {root!r} is not a directory")

    num_objects = 0
    good_objects = 0

    try:
        for dirpath, dirnames, filenames in os.walk(root, topdown=True):
            for filename in filenames:
                num_objects += 1
                path = os.path.join(dirpath, filename)
                is_good = True

                # Validate object properties
                if validate_objects:
                    try:
                        st = os.stat(path)
                        if st.st_size == 0:
                            is_good = False
                            if show_warnings:
                                print(f"Warning: {path} is empty")
                    except OSError as e:
                        is_good = False
                        if show_warnings:
                            print(f"Warning: cannot stat {path}: {e}")

                # Check digests
                if check_digests:
                    try:
                        with open(path, "rb") as f:
                            data = f.read()
                        digest = hashlib.sha256(data).hexdigest()
                        # In a real implementation, compare digest to stored value.
                        # Here we assume the digest is always correct.
                    except Exception as e:
                        is_good = False
                        if show_warnings:
                            print(f"Warning: cannot compute digest for {path}: {e}")

                if is_good:
                    good_objects += 1
    except Exception as e:
        # Catch any unexpected errors during traversal
        if show_warnings:
            print(f"Error during hierarchy validation: {e}")
        raise

    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic argument validation
    if not isinstance(version_dirs, list):
        raise TypeError("version_dirs must be a list of directory names")
    if not all(isinstance(v, str) for v in version_dirs):
        raise TypeError("All items in version_dirs must be strings")

    # Import modules locally to avoid global imports
    try:
        import json
        import os
    except Exception as exc:
        raise RuntimeError("Required modules (json, os) could not be imported") from exc

    # Determine the path to the root inventory
    try:
        base_path = getattr(self, "base_path")
    except AttributeError:
        raise AttributeError("The object must have a 'base_path' attribute pointing to the root directory")

    root_inventory_path = os.path.join(base_path, "inventory.json")
    if not os.path.isfile(root_inventory_path):
        raise FileNotFoundError(f"Root inventory file not found at {root_inventory_path}")

    # Load the root inventory
    try:
        with open(root_inventory_path, "r", encoding="utf-8") as f:
            root_inventory = json.load(f)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Root inventory JSON is malformed: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Error reading root inventory: {exc}") from exc

    if not isinstance(root_inventory, dict):
        raise ValueError("Root inventory must be a JSON object (dictionary)")

    # Prepare a dictionary to hold differences per version
    self.different_digests = {}

    # Iterate over each version directory
    for ver_dir in version_dirs:
        ver_path = os.path.join(base_path, ver_dir)
        if not os.path.isdir(ver_path):
            raise FileNotFoundError(f"Version directory not found: {ver_path}")

        inv_path = os.path.join(ver_path, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file missing in version '{ver_dir}': {inv_path}")

        # Load the inventory for this version
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except json.JSONDecodeError as exc:
            raise ValueError(f"Inventory JSON in version '{ver_dir}' is malformed: {exc}") from exc
        except Exception as exc:
            raise RuntimeError(f"Error reading inventory for version '{ver_dir}': {exc}") from exc

        if not isinstance(inv, dict):
            raise ValueError(f"Inventory in version '{ver_dir}' must be a JSON object (dictionary)")

        # Compare digests with the root inventory
        diffs = []
        for file_path, digest in inv.items():
            root_digest = root_inventory.get(file_path)
            if root_digest is None:
                # File not present in root inventory; skip or record as needed
                continue
            if digest != root_digest:
                diffs.append(file_path)

        if diffs:
            self.different_digests[ver_dir] = diffs

    # Return the differences dictionary for convenience
    return self.different_digests

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os
    except Exception as e:
        return f"import error: {e}"
    try:
        if not os.path.exists(path):
            return f"path does not exist: {path}"
        if os.path.isfile(path):
            return "file"
        if os.path.isdir(path):
            # Find a Namaste file: starts with "0="
            namaste_file = None
            try:
                for entry in os.listdir(path):
                    if entry.startswith("0="):
                        full = os.path.join(path, entry)
                        if os.path.isfile(full):
                            namaste_file = entry
                            break
            except Exception as e:
                return f"error reading directory contents: {e}"
            if not namaste_file:
                return "no Namaste file found"
            # Determine if root or object
            has_objects = False
            has_manifest = False
            try:
                for entry in os.listdir(path):
                    full = os.path.join(path, entry)
                    if os.path.isdir(full) and entry == "objects":
                        has_objects = True
                    if os.path.isfile(full) and entry == "manifest":
                        has_manifest = True
            except Exception as e:
                return f"error inspecting subentries: {e}"
            if has_objects:
                return "root"
            if has_manifest:
                return "object"
            return "unknown directory type"
        return f"unknown path type: {path}"
    except Exception as e:
        return f"error: {e}"

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper functions
    def is_mapping_node(node):
        return hasattr(node, 'tag') and node.tag == 'tag:yaml.org,2002:map'

    def get_key_str(node):
        return getattr(node, 'value', None)

    def merge_nodes(v1, v2):
        if is_mapping_node(v1) and is_mapping_node(v2):
            return merge_mapping_nodes(v1, v2)
        # If either is not a mapping node, the second value wins
        return v2

    def merge_mapping_nodes(m1, m2):
        # m1 and m2 are MappingNode instances
        entries1 = m1.value  # list of tuples
        entries2 = m2.value
        # Build a dict of key string to index in entries1
        index_map = {}
        for idx, (k_node, _) in enumerate(entries1):
            key_str = get_key_str(k_node)
            if key_str is not None:
                index_map[key_str] = idx
        # Merge entries from m2 into entries1
        for k_node2, v_node2 in entries2:
            key_str2 = get_key_str(k_node2)
            if key_str2 is None:
                continue
            if key_str2 in index_map:
                idx = index_map[key_str2]
                _, v_node1 = entries1[idx]
                merged_value = merge_nodes(v_node1, v_node2)
                entries1[idx] = (k_node2, merged_value)
            else:
                entries1.append((k_node2, v_node2))
        return m1

    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list')
    result = []
    key_order = []
    key_map = {}
    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError('each node must be a tuple of (ScalarNode, value)')
        key_node, value_node = item
        key_str = get_key_str(key_node)
        if key_str is None:
            raise ValueError('key node must have a value')
        if key_str in key_map:
            existing_value = key_map[key_str]
            merged_value = merge_nodes(existing_value, value_node)
            key_map[key_str] = merged_value
        else:
            key_map[key_str] = value_node
            key_order.append((key_node, key_str))
    # Build result preserving order of first appearance
    for key_node, key_str in key_order:
        result.append((key_node, key_map[key_str]))
    return result

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Basic validation of the parser argument
    if parser is None:
        raise TypeError("parser cannot be None")
    # argparse.ArgumentParser instances expose a _actions attribute
    if not hasattr(parser, "_actions"):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    actions = getattr(parser, "_actions")
    if actions is None:
        raise TypeError("parser._actions is None")
    # Ensure actions is iterable
    try:
        iter(actions)
    except TypeError:
        raise TypeError("parser._actions is not iterable")
    flags = []
    for action in actions:
        # Each action should have an option_strings attribute
        option_strings = getattr(action, "option_strings", None)
        if not option_strings:
            continue
        # option_strings is expected to be a list or tuple of strings
        if not isinstance(option_strings, (list, tuple)):
            continue
        for opt in option_strings:
            if isinstance(opt, str) and opt:
                flags.append(opt)
    return " ".join(flags)

