    if not isinstance(nodes, list):
        raise ValueError('nodes must be a list')
    for idx, item in enumerate(nodes):
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError(f'node at index {idx} is not a 2-tuple')
        key_node, val_node = item
        if not hasattr(key_node, 'value'):
            raise ValueError(f'key at index {idx} is not a ScalarNode')

    # Helper to merge two MappingNode values
    def merge_mapping_nodes(existing_map, new_map):
        # existing_map and new_map are MappingNode instances
        existing_pairs = existing_map.value
        new_pairs = new_map.value

        # Build dict of existing key -> (key_node, value_node)
        existing_dict = {k.value: (k, v) for k, v in existing_pairs}

        # Prepare list for merged pairs
        merged_pairs = []

        # Process existing pairs first
        for k_node, v_node in existing_pairs:
            key = k_node.value
            if key in new_dict:
                new_k_node, new_v_node = new_dict[key]
                # Merge if both are MappingNode
                if isinstance(v_node, type(existing_map)) and isinstance(new_v_node, type(new_map)):
                    merged_v = merge_mapping_nodes(v_node, new_v_node)
                    merged_pairs.append((k_node, merged_v))
                else:
                    # Replace with new value
                    merged_pairs.append((k_node, new_v_node))
                # Mark as processed
                processed_keys.add(key)
            else:
                merged_pairs.append((k_node, v_node))

        # Add new pairs that were not in existing
        for k_node, v_node in new_pairs:
            key = k_node.value
            if key not in processed_keys:
                merged_pairs.append((k_node, v_node))

        # Update existing_map's value
        existing_map.value = merged_pairs
        return existing_map

    # Helper to merge two nodes
    def merge_nodes(existing_node, new_node):
        if isinstance(existing_node, type(new_node)) and isinstance(existing_node, MappingNode):
            return merge_mapping_nodes(existing_node, new_node)
        else:
            return new_node

    # Main merging logic
    merged = []
    key_to_index = {}
    for key_node, val_node in nodes:
        key = key_node.value
        if key in key_to_index:
            idx = key_to_index[key]
            existing_key_node, existing_val_node = merged[idx]
            merged_val_node = merge_nodes(existing_val_node, val_node)
            merged[idx] = (existing_key_node, merged_val_node)
        else:
            key_to_index[key] = len(merged)
            merged.append((key_node, val_node))

    return merged

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Basic validation: parser must be an argparse.ArgumentParser instance
    if parser is None:
        raise TypeError("parser cannot be None")
    # Check for the presence of the internal actions list
    if not hasattr(parser, "_actions"):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    # Optional: ensure the class name and module match argparse.ArgumentParser
    cls = parser.__class__
    if cls.__name__ != "ArgumentParser" or cls.__module__ != "argparse":
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    # Collect all option strings from each action
    flags = []
    for action in parser._actions:
        # Each action should have an option_strings attribute
        if hasattr(action, "option_strings"):
            flags.extend(action.option_strings)
    # Return a space‑separated string of flags
    return " ".join(flags)

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("dicts must be an iterable of dictionaries, got None")
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"Dictionary values must be numeric, got {type(value).__name__} for key {key}")
            result[key] = result.get(key, 0) + value
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        if not isinstance(val, str):
            return False
        stripped = val.strip().lower()
        return stripped in {"none", "null", "nil"}
    except Exception:
        return False

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Basic validation of the input
    if parser is None:
        raise TypeError("parser must not be None")
    if not hasattr(parser, "_actions"):
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    # Collect all option strings from the parser's actions
    flags = []
    for action in parser._actions:
        # action.option_strings is a list of flag strings (e.g., ['-h', '--help'])
        if hasattr(action, "option_strings"):
            flags.extend(action.option_strings)

    # Return the flags as a single space-separated string
    return " ".join(flags)

def _replace_register(flow_params, register_number, register_value):
    """
    Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    :return: The updated flow_params dictionary
    """
    # Basic type validation
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, int):
        raise TypeError("register_number must be an integer")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string key")

    found = False
    for flow_name, flow_content in flow_params.items():
        if isinstance(flow_content, dict):
            if register_value in flow_content:
                flow_content[register_value] = register_number
                found = True
        else:
            # If flow_content is not a dict, skip or raise warning
            continue

    if not found:
        raise KeyError(f"Key '{register_value}' not found in any flow")

    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("cls must be a class")
    result = set()
    def _collect(c):
        for sub in c.__subclasses__():
            if sub not in result:
                result.add(sub)
                _collect(sub)
    _collect(cls)
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must not be empty.")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet contains duplicate entries.")
    base = len(alphabet)
    char_to_value = {char: idx for idx, char in enumerate(alphabet)}
    if not string:
        raise ValueError("Input string must not be empty.")
    result = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' not found in alphabet.")
        result = result * base + char_to_value[ch]
    return result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        # On Unix-like systems, os.uname() is available and returns a tuple-like object
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        # os.uname() is not available on Windows; try environment variable
        try:
            return os.getenv('OSTYPE', '').lower() == 'darwin'
        except Exception:
            return False
    except Exception:
        return False

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError("Input must be a dictionary")
    result = {}
    for key, value in item.items():
        if not isinstance(key, str):
            raise ValueError(f"Dictionary key must be a string, got {type(key).__name__}")
        # Escape all regex special characters except '*', then replace '*' with '.*'
        escaped = re.escape(key).replace(r'\*', '.*')
        pattern = f"^{escaped}$"
        try:
            regex = re.compile(pattern)
        except re.error as exc:
            raise ValueError(f"Invalid regex pattern derived from key '{key}': {exc}") from exc
        result[regex] = value
    return result

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Strip surrounding single or double quotes
    if len(name) >= 2 and name[0] == name[-1] and name[0] in ("'", '"'):
        return name[1:-1]
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Validate input
    if not isinstance(s, str):
        raise TypeError(f"Expected string input, got {type(s).__name__}")
    # Determine platform
    if platform == 'this':
        import sys
        platform = 0 if sys.platform.startswith('win') else 1
    if platform not in (0, 1):
        raise ValueError(f"Unsupported platform value: {platform}")
    # Handle empty string
    if not s:
        return []
    # POSIX implementation using regex
    if platform == 1:
        # Regex to match double-quoted, single-quoted, or unquoted tokens
        token_re = re.compile(r'''(?:"((?:\\.|[^"\\])*)"|'((?:\\.|[^'\\])*)'|(\S+))''')
        args = []
        for m in token_re.finditer(s):
            dbl, sgl, unq = m.group(1), m.group(2), m.group(3)
            if dbl is not None:
                # Remove backslash escapes
                token = re.sub(r'\\(.)', r'\1', dbl)
            elif sgl is not None:
                token = sgl  # single quotes preserve backslashes
            else:
                token = re.sub(r'\\(.)', r'\1', unq)
            args.append(token)
        return args
    # Windows implementation
    if platform == 0:
        args = []
        current = []
        in_quotes = False
        i = 0
        length = len(s)
        while i < length:
            c = s[i]
            if in_quotes:
                if c == '\\':
                    # Count consecutive backslashes
                    backslash_count = 0
                    while i < length and s[i] == '\\':
                        backslash_count += 1
                        i += 1
                    if i < length and s[i] == '"':
                        # Backslashes before a quote
                        current.extend(['\\'] * (backslash_count // 2))
                        if backslash_count % 2 == 1:
                            # Escaped quote
                            current.append('"')
                            i += 1
                        else:
                            # End of quoted string
                            i += 1
                            in_quotes = False
                    else:
                        # Backslashes not before a quote
                        current.extend(['\\'] * backslash_count)
                        continue
                elif c == '"':
                    # End quoted string
                    in_quotes = False
                    i += 1
                else:
                    current.append(c)
                    i += 1
            else:
                if c.isspace():
                    if current:
                        args.append(''.join(current))
                        current = []
                    i += 1
                elif c == '"':
                    in_quotes = True
                    i += 1
                else:
                    current.append(c)
                    i += 1
        if current:
            args.append(''.join(current))
        return args
    # Should not reach here
    raise RuntimeError("Unhandled platform case")

