def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if host is None:
        raise ValueError("host must not be None")
    host = host.strip()
    if not host:
        raise ValueError("host must not be empty")

    # Direct string checks for common localhost identifiers
    if host.lower() == "localhost":
        return True
    if host == "127.0.0.1" or host == "::1":
        return True

    try:
        # Resolve the host to all possible addresses
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                if ip == "::1":
                    return True
    except socket.gaierror:
        # Host could not be resolved; treat as not local
        return False
    except Exception:
        # Any other unexpected error should be treated as not local
        return False

    return False

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    if find_paths is None:
        raise ValueError("find_paths cannot be None")
    try:
        iterator = iter(find_paths)
    except TypeError:
        raise TypeError("find_paths must be an iterable of strings")
    result = []
    for item in iterator:
        if not isinstance(item, str):
            raise TypeError(f"find_paths elements must be strings, got {type(item).__name__}")
        # If the item contains a colon, treat it as an existing pattern and leave it unchanged
        if ':' in item:
            result.append(item)
        else:
            # Transform the fragment into a glob pattern
            result.append(f"sh:**/*{item}*/**")
    return result

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    # Only possible on Windows
    if os.name != 'nt':
        return False

    # Check environment variables that Git Bash sets
    ostype = os.environ.get('OSTYPE', '').lower()
    if 'msys' in ostype or 'cygwin' in ostype:
        return True

    # MSYSTEM is set by Git Bash (e.g., MINGW64, MINGW32)
    if os.environ.get('MSYSTEM', '').startswith('MINGW'):
        return True

    # As a fallback, check if the current executable is bash
    try:
        import sys
        if 'bash' in sys.argv[0].lower():
            return True
    except Exception:
        pass

    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    """
    # Validate arguments
    if not isinstance(config_filename, str):
        raise TypeError("config_filename must be a string")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # Ensure parent directories exist
    dirpath = os.path.dirname(config_filename)
    if dirpath:
        try:
            os.makedirs(dirpath, exist_ok=True)
        except Exception as exc:
            raise OSError(f"Failed to create directories for '{config_filename}': {exc}") from exc

    # Check for existing file
    if os.path.exists(config_filename) and not overwrite:
        raise FileExistsError(f"File '{config_filename}' already exists and overwrite is False")

    # Write the configuration file
    try:
        with open(config_filename, "w", encoding="utf-8") as f:
            f.write(rendered_config)
        os.chmod(config_filename, mode)
    except Exception as exc:
        raise OSError(f"Failed to write configuration to '{config_filename}': {exc}") from exc
    return None

def subprocess_run_helper(func, *args, timeout, extra_env=None):
    import subprocess, sys, os, inspect, importlib
    # Validate func
    if not callable(func):
        raise TypeError("func must be callable")
    module = inspect.getmodule(func)
    if module is None or not hasattr(module, "__name__"):
        raise ValueError("func must be defined in an importable module")
    module_name = module.__name__
    # Ensure module is importable
    try:
        importlib.import_module(module_name)
    except Exception as e:
        raise ValueError(f"Module {module_name} is not importable: {e}") from e
    func_name = func.__name__
    # Validate args
    for a in args:
        if not isinstance(a, str):
            raise TypeError("All args must be strings")
    # Validate timeout
    if not isinstance(timeout, (int, float)) or timeout <= 0:
        raise ValueError("timeout must be a positive number")
    # Validate extra_env
    if extra_env is not None:
        if not isinstance(extra_env, dict):
            raise TypeError("extra_env must be a dict")
        for k, v in extra_env.items():
            if not isinstance(k, str) or not isinstance(v, str):
                raise TypeError("extra_env keys and values must be strings")
    # Build command
    cmd = [sys.executable, "-c", f"import {module_name}; {module_name}.{func_name}()", *args]
    env = os.environ.copy()
    if extra_env:
        env.update(extra_env)
    try:
        result = subprocess.run(cmd, timeout=timeout, env=env, capture_output=True, text=True)
    except subprocess.TimeoutExpired as e:
        raise TimeoutError(f"Subprocess timed out after {timeout} seconds") from e
    except Exception as e:
        raise RuntimeError(f"Failed to run subprocess: {e}") from e
    return result

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    if matcher is None:
        raise ValueError("Matcher cannot be None")

    # Support matcher as a string or a tuple/list
    if isinstance(matcher, (list, tuple)):
        if len(matcher) == 1:
            name, default = matcher[0], None
        elif len(matcher) == 2:
            name, default = matcher
        else:
            raise ValueError("Matcher tuple/list must contain 1 or 2 elements")
    elif isinstance(matcher, str):
        if ':' in matcher:
            name, default = matcher.split(':', 1)
        else:
            name, default = matcher, None
    else:
        raise TypeError("Matcher must be a string or a tuple/list")

    name = name.strip()
    if not name:
        raise ValueError("Environment variable name cannot be empty")

    if default is not None:
        default = default.strip()

    value = os.environ.get(name)
    if value is not None:
        return value
    if default is not None:
        return default
    raise KeyError(f"Environment variable '{name}' not found and no default provided")

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    try:
        if not isinstance(pattern, str):
            raise TypeError("pattern must be a string")
        if strip:
            pattern = pattern.strip()
        # Escape regex special characters
        regex_pattern = re.escape(pattern)
        return regex_pattern
    except Exception as e:
        raise ValueError(f"Error converting pattern to regex: {e}") from e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if isinstance(commands, str):
        commands_list = [commands]
    elif isinstance(commands, (list, tuple)):
        commands_list = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")

    if args is None:
        args_list = []
    elif isinstance(args, (list, tuple)):
        args_list = list(args)
    else:
        raise TypeError("args must be a list or tuple of strings")

    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string or None")

    if not isinstance(verbose, bool):
        raise TypeError("verbose must be a boolean")

    if not isinstance(hide_stderr, bool):
        raise TypeError("hide_stderr must be a boolean")

    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    if not commands_list:
        raise ValueError("commands list cannot be empty")

    last_exception = None

    for cmd in commands_list:
        if not isinstance(cmd, str):
            raise TypeError("each command must be a string")

        full_cmd = [cmd] + args_list

        if verbose:
            # Simple representation; may not handle quoting of arguments with spaces
            print("Running command:", " ".join(full_cmd))

        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
                text=True,
                check=True
            )
            return result
        except FileNotFoundError as e:
            last_exception = e
            continue
        except subprocess.CalledProcessError as e:
            # Command was found but returned a non-zero exit status
            raise

    # If we reach here, all commands failed to be found
    if last_exception:
        raise last_exception
    else:
        raise FileNotFoundError(f"Command not found: {commands_list}")

