def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate shape
    if not isinstance(shape, (tuple, list)):
        raise TypeError(f"shape must be a tuple or list of integers, got {type(shape).__name__}")
    if not all(isinstance(dim, int) and dim >= 0 for dim in shape):
        raise ValueError("All dimensions in shape must be non-negative integers")

    # Validate dtype
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"dtype must be a valid numpy dtype, got {dtype}") from exc

    # Create the array
    try:
        return np.zeros(shape, dtype=dtype_obj)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array with shape {shape} and dtype {dtype_obj}") from exc

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    if x is None:
        raise ValueError("Input x cannot be None.")
    try:
        arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise TypeError("Input x must be numeric.") from e
    mu = 0.2
    sigma = 0.1
    return np.exp(-((arr - mu)**2) / (2 * sigma**2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import os
    import re
    import logging
    import configparser

    # Validate input types
    if not hasattr(config_filenames, '__iter__'):
        raise TypeError("config_filenames must be an iterable of filenames")
    if overrides is not None and not isinstance(overrides, dict):
        raise TypeError("overrides must be a dict or None")
    if not isinstance(resolve_env, bool):
        raise TypeError("resolve_env must be a boolean")

    results = {}
    error_records = []

    # Helper to create a LogRecord for errors
    def _make_error_record(msg, exc_info=None):
        return logging.LogRecord(
            name='load_configurations',
            level=logging.ERROR,
            pathname=__file__,
            lineno=0,
            msg=msg,
            args=(),
            exc_info=exc_info
        )

    # Helper to resolve environment variables in strings
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def _resolve_env_in_value(value):
        if isinstance(value, str):
            def repl(match):
                var = match.group(1)
                return os.getenv(var, '')
            return env_pattern.sub(repl, value)
        return value

    def _walk_and_resolve(obj):
        if isinstance(obj, dict):
            return {k: _walk_and_resolve(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_walk_and_resolve(v) for v in obj]
        else:
            return _resolve_env_in_value(obj)

    for filename in config_filenames:
        if not isinstance(filename, str):
            error_records.append(_make_error_record(f"Filename {filename!r} is not a string"))
            continue
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as e:
            error_records.append(_make_error_record(f"Failed to read file {filename!r}: {e}", exc_info=True))
            continue

        parsed = None
        # Try JSON
        try:
            parsed = json.loads(content)
        except Exception:
            pass

        # Try YAML if json failed
        if parsed is None:
            try:
                import yaml
                parsed = yaml.safe_load(content)
            except Exception:
                pass

        # Try INI if still None
        if parsed is None:
            try:
                parser = configparser.ConfigParser()
                parser.read_file(io.StringIO(content))
                parsed = {section: dict(parser.items(section)) for section in parser.sections()}
            except Exception:
                pass

        if parsed is None:
            error_records.append(_make_error_record(f"Could not parse configuration file {filename!r}"))
            continue

        if not isinstance(parsed, dict):
            error_records.append(_make_error_record(f"Parsed configuration from {filename!r} is not a dict"))
            continue

        # Apply overrides
        if overrides:
            for key, value in overrides.items():
                parsed[key] = value

        # Resolve environment variables
        if resolve_env:
            parsed = _walk_and_resolve(parsed)

        results[filename] = parsed

    return results, error_records

@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        if values is None:
            raise TypeError("values must be an iterable of strings")
        try:
            iterator = iter(values)
        except TypeError:
            raise TypeError("values must be an iterable of strings")
        raw_values = []
        for v in iterator:
            if not isinstance(v, str):
                raise ValueError(f"Bookmark value must be a string, got {type(v).__name__}")
            try:
                v.encode('ascii')
            except UnicodeEncodeError:
                raise ValueError(f"Bookmark value must be ASCII: {v!r}")
            raw_values.append(v)
        try:
            return cls(raw_values)
        except Exception as e:
            raise RuntimeError(f"Failed to create Bookmarks from raw values: {e}") from e

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Validate get_coordinate
    valid_coords = {"left", "right", "middle"}
    if get_coordinate not in valid_coords:
        raise ValueError(f"get_coordinate must be one of {valid_coords}, got {get_coordinate!r}")

    # Determine scale
    if scale is True:
        try:
            scale = getattr(hist, "scale", None)
        except Exception as exc:
            raise ValueError("Histogram has no 'scale' attribute") from exc
    # If scale is None, keep it as None

    # Prepare make_value
    if make_value is None:
        def make_value(x):  # noqa: D401
            """Default make_value returns the bin content."""
            return x

    # Prepare points list
    points = []

    # Attempt to iterate over histogram bins
    try:
        bins = getattr(hist, "bins")
    except Exception as exc:
        raise ValueError("Histogram object must have a 'bins' attribute") from exc

    if not hasattr(bins, "__iter__"):
        raise ValueError("'bins' attribute must be iterable")

    # Helper to get coordinate from a bin
    def _get_coord(bin_obj, coord_name):
        # Try common attribute names
        for attr in (coord_name, f"{coord_name}_edge", f"{coord_name}_edge", f"{coord_name}_edge",
                     f"{coord_name}_edge", f"{coord_name}_edge", f"{coord_name}_edge"):
            if hasattr(bin_obj, attr):
                return getattr(bin_obj, attr)
        # Fallback: try left/right/middle properties
        if coord_name == "left" and hasattr(bin_obj, "left"):
            return bin_obj.left
        if coord_name == "right" and hasattr(bin_obj, "right"):
            return bin_obj.right
        if coord_name == "middle" and hasattr(bin_obj, "middle"):
            return bin_obj.middle
        # As a last resort, try edges list
        if hasattr(bin_obj, "edges") and isinstance(bin_obj.edges, (list, tuple)):
            edges = bin_obj.edges
            if coord_name == "left":
                return edges[0]
            if coord_name == "right":
                return edges[-1]
            if coord_name == "middle":
                return sum(edges) / len(edges)
        raise AttributeError(f"Cannot find coordinate '{coord_name}' in bin object")

    # Helper to get bin content
    def _get_content(bin_obj):
        for attr in ("content", "value", "count", "entries"):
            if hasattr(bin_obj, attr):
                return getattr(bin_obj, attr)
        # If bin_obj is a simple numeric type
        if isinstance(bin_obj, (int, float)):
            return bin_obj
        raise AttributeError("Bin object has no recognizable content attribute")

    # Process each bin
    for bin_obj in bins:
        try:
            coord = _get_coord(bin_obj, get_coordinate)
        except Exception as exc:
            raise ValueError(f"Failed to get coordinate from bin: {exc}") from exc

        try:
            content = _get_content(bin_obj)
        except Exception as exc:
            raise ValueError(f"Failed to get content from bin: {exc}") from exc

        try:
            value = make_value(content)
        except Exception as exc:
            raise ValueError(f"make_value function raised an exception: {exc}") from exc

        # Ensure value is iterable if multiple fields
        if isinstance(value, (tuple, list)):
            val_tuple = tuple(value)
        else:
            val_tuple = (value,)

        # Validate field_names length
        if len(field_names) != len(val_tuple):
            raise ValueError(f"field_names length {len(field_names)} does not match "
                             f"make_value output length {len(val_tuple)}")

        point = (coord, *val_tuple)
        points.append(point)

    # Create graph object
    try:
        graph = Graph(points, scale=scale, field_names=field_names)
    except Exception as exc:
        raise ValueError(f"Failed to create Graph object: {exc}") from exc

    return graph

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if default is __marker:
        # No default provided; let the underlying implementation raise KeyError if missing
        return super().pop(key)
    else:
        # Default provided; return it if key is missing
        return super().pop(key, default)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    cache = getattr(self, "_cache", None)
    if cache is None:
        raise AttributeError("The object does not have a '_cache' attribute")
    if not cache:
        raise KeyError("popitem(): dictionary is empty")
    try:
        # Attempt to use OrderedDict's popitem with last=False
        return cache.popitem(last=False)
    except TypeError:
        # Fallback for non-OrderedDict implementations
        order = getattr(self, "_order", None)
        if order is None or not isinstance(order, list):
            raise NotImplementedError(
                "popitem is not implemented for this cache type"
            )
        if not order:
            raise KeyError("popitem(): dictionary is empty")
        key = order.pop(0)
        try:
            value = cache.pop(key)
        except KeyError:
            raise KeyError(f"Key {key} not found in cache during popitem")
        return key, value
    except Exception as exc:
        raise RuntimeError("An unexpected error occurred during popitem") from exc

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # The cache is expected to be stored in an attribute named `_cache`.
    if not hasattr(self, "_cache"):
        raise AttributeError("Missing '_cache' attribute")
    cache = self._cache
    if not cache:
        raise KeyError("dictionary is empty")
    # Try to use OrderedDict's popitem with last=True
    if hasattr(cache, "popitem"):
        try:
            return cache.popitem(last=True)
        except TypeError:
            # Fallback for plain dict: pop the last inserted key
            key = next(reversed(cache))
            value = cache.pop(key)
            return key, value
    # If cache has no popitem, fall back to dict behavior
    key = next(reversed(cache))
    value = cache.pop(key)
    return key, value

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        # Matches strings that start with optional whitespace, followed by "in:",
        # optional whitespace, and then captures the rest of the line as params.
        return re.compile(r"^\s*in\s*:\s*(?P<params>.+)$")
    except re.error as exc:
        raise ValueError(f"Failed to compile in-style regex: {exc}") from exc

def identify_request(request):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    if request is None:
        raise ValueError("request cannot be None")

    def _has_value(obj, key):
        try:
            if isinstance(obj, dict):
                return key in obj and obj[key] is not None
            return hasattr(obj, key) and getattr(obj, key) is not None
        except Exception:
            return False

    # Check for a public message
    if _has_value(request, "public_message"):
        return True

    # Check for a private message
    if _has_value(request, "private_message"):
        return True

    # Check for a legacy payload
    if _has_value(request, "legacy_payload"):
        return True

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    if request is None:
        raise ValueError("request cannot be None")

    try:
        # If request is a dictionary, look for typical Matrix keys
        if isinstance(request, dict):
            keys = set(request.keys())
            # Common Matrix request fields
            if {'type', 'content'}.issubset(keys):
                return True
            if 'room_id' in keys or 'event_id' in keys:
                return True
            # Some Matrix requests may only contain a single 'type' key
            if 'type' in keys:
                return True

        # If request is an object, inspect its attributes
        else:
            # Gather public attributes
            attrs = [attr for attr in dir(request) if not attr.startswith('_')]
            if 'type' in attrs and 'content' in attrs:
                return True
            if 'room_id' in attrs or 'event_id' in attrs:
                return True
            if 'type' in attrs:
                return True

    except Exception:
        # Any unexpected error during inspection results in False
        return False

    return False

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    try:
        import urllib.request
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.headers.get('Content-Type')
    except Exception:
        return None

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        raise ValueError("node cannot be None")
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("node must be an XML element-like object") from exc

    result = {}
    for child in children:
        # If multiple children share the same tag, the last one will overwrite earlier ones.
        result[child.tag] = child
    return result

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    if sender_handle is None or entity_handle is None:
        raise ValueError("Sender or entity handle is None")
    if sender_handle != entity_handle:
        raise ValueError(f"Sender handle '{sender_handle}' does not match entity handle '{entity_handle}'")

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate url
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    url = url.strip()
    if not url:
        raise ValueError("url cannot be empty")
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("url must start with http:// or https://")

    # Validate document_path
    if document_path is not None:
        if not isinstance(document_path, str):
            raise TypeError("document_path must be a string if provided")
        document_path = document_path.strip()
        if document_path == "":
            document_path = None

    # Default NodeInfo endpoint
    default_path = "/nodeinfo/2.0"
    path = document_path if document_path is not None else default_path

    # Ensure path starts with a slash
    if not path.startswith("/"):
        path = "/" + path

    # Build the full href
    base = url.rstrip("/")
    href = base + path

    # Construct the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Document must be a non-empty string")

    doc = document.strip()
    # Try JSON first
    if doc[0] in ('{', '['):
        try:
            import json
            data = json.loads(doc)
        except Exception as e:
            raise ValueError(f"Invalid JSON webfinger document: {e}") from e
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger must be an object")
        # Ensure required keys
        subject = data.get("subject")
        aliases = data.get("aliases", [])
        links = data.get("links", [])
        if subject is None:
            raise ValueError("JSON webfinger missing 'subject'")
        if not isinstance(aliases, list):
            raise ValueError("'aliases' must be a list")
        if not isinstance(links, list):
            raise ValueError("'links' must be a list")
        return {"subject": subject, "aliases": aliases, "links": links}

    # Otherwise treat as XRD (XML)
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(doc)
    except Exception as e:
        raise ValueError(f"Invalid XRD webfinger document: {e}") from e

    # Helper to find elements ignoring namespace
    def find_text(elem, tag):
        for child in elem.iter():
            if child.tag.endswith(tag):
                return child.text
        return None

    def find_all_text(elem, tag):
        texts = []
        for child in elem.iter():
            if child.tag.endswith(tag):
                if child.text:
                    texts.append(child.text)
        return texts

    subject = find_text(root, "Subject")
    if subject is None:
        raise ValueError("XRD webfinger missing <Subject> element")

    aliases = find_all_text(root, "Alias")

    links = []
    for link_elem in root.iter():
        if link_elem.tag.endswith("Link"):
            # Extract attributes
            link_attrs = dict(link_elem.attrib)
            # If href attribute missing, skip
            if "href" not in link_attrs:
                continue
            links.append(link_attrs)

    return {"subject": subject, "aliases": aliases, "links": links}

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """
    Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Validate method
    if not isinstance(method, str):
        raise ValueError("method must be a string")
    method = method.lower()

    # Ensure timeout is a number
    try:
        timeout_val = float(timeout)
    except Exception as exc:
        raise ValueError("timeout must be a number") from exc

    # Prepare kwargs: remove any 'timeout' key to avoid conflict
    kwargs = dict(kwargs)  # make a copy
    kwargs.pop("timeout", None)

    try:
        import requests  # assume requests is available

        if method == "post":
            response = requests.post(url, data=data, timeout=timeout_val, *args, **kwargs)
        else:
            response = requests.request(method, url, data=data, timeout=timeout_val, *args, **kwargs)

        # Return status code and no error
        return (response.status_code, None)
    except Exception as e:
        # Return None for status code and the exception instance
        return (None, e)

def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file paths found in the directories specified by `settings_dirs`.
    If `spec_option` is provided, it is used to filter the files:
        - If it contains wildcard characters (*, ?, [), it is treated as a glob pattern.
        - Otherwise it is treated as a file extension (e.g., ".ini").
    Parameters
    ----------
    settings_dirs : Iterable[str]
        An iterable of directory paths to search for files.
    spec_option : str or None
        Optional filter for file names. Can be a glob pattern or a file extension.
    Returns
    -------
    List[str]
        A list of full file paths that match the criteria.
    Raises
    ------
    TypeError
        If `settings_dirs` is not iterable or `spec_option` is not a string or None.
    """
    import os
    import fnmatch

    # Validate inputs
    if not hasattr(settings_dirs, "__iter__") or isinstance(settings_dirs, (str, bytes)):
        raise TypeError("settings_dirs must be an iterable of directory paths")
    if spec_option is not None and not isinstance(spec_option, str):
        raise TypeError("spec_option must be a string or None")

    # Determine if spec_option is a glob pattern
    use_glob = False
    if spec_option:
        if any(ch in spec_option for ch in "*?[]"):
            use_glob = True

    matched_files = []

    for dir_path in settings_dirs:
        try:
            if not os.path.isdir(dir_path):
                continue  # Skip non-existent or non-directory paths
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if not os.path.isfile(full_path):
                    continue
                if spec_option is None:
                    matched_files.append(full_path)
                else:
                    if use_glob:
                        if fnmatch.fnmatch(entry, spec_option):
                            matched_files.append(full_path)
                    else:
                        if entry.lower().endswith(spec_option.lower()):
                            matched_files.append(full_path)
        except OSError:
            # Skip directories that cannot be accessed
            continue

    return sorted(matched_files)

@classmethod
def ansible_config_manager(cls):
    """Gets the ansible config manager."""
    try:
        from ansible.constants import CONSTANTS
        return CONSTANTS
    except ImportError as e:
        raise ImportError("Ansible is not installed or cannot import ansible.constants") from e
    except AttributeError as e:
        raise AttributeError("ansible.constants.CONSTANTS not found") from e

@classmethod
def workspace_manager(cls):
    """Gets the workspace manager."""
    try:
        if not hasattr(cls, "_workspace_manager"):
            # Define a simple workspace manager if one does not exist
            class _WorkspaceManager:
                def __init__(self):
                    self._workspaces = []

                def add_workspace(self, workspace):
                    """Add a workspace to the manager."""
                    if workspace is None:
                        raise ValueError("workspace cannot be None")
                    self._workspaces.append(workspace)

                def list_workspaces(self):
                    """Return a list of all managed workspaces."""
                    return list(self._workspaces)

                def clear(self):
                    """Remove all workspaces from the manager."""
                    self._workspaces.clear()

            cls._workspace_manager = _WorkspaceManager()
        return cls._workspace_manager
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve workspace manager: {exc}") from exc

@classmethod
def plugins_manager(cls):
    """Gets the plugin manager."""
    try:
        if not hasattr(cls, "_plugins_manager"):
            cls._plugins_manager = {}
        return cls._plugins_manager
    except Exception as exc:
        raise RuntimeError("Unable to retrieve plugin manager") from exc

@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    # Define a local exception class if not already defined
    try:
        IRValidatorException = cls.IRValidatorException
    except AttributeError:
        class IRValidatorException(Exception):
            pass

    # Helper to load YAML if necessary
    def _load_yaml(content):
        import yaml
        try:
            return yaml.safe_load(content)
        except Exception as exc:
            raise IRValidatorException(f"Invalid YAML content: {exc}") from exc

    # Ensure spec_content is provided
    if spec_content is None:
        raise IRValidatorException("Spec content is None")

    # If spec_content is a string, attempt to parse it as YAML
    if isinstance(spec_content, str):
        spec_dict = _load_yaml(spec_content)
    else:
        spec_dict = spec_content

    # Spec must be a mapping
    if not isinstance(spec_dict, dict):
        raise IRValidatorException("Spec content must be a mapping (dictionary)")

    # Define required fields (adjust as needed for your spec)
    required_fields = ["name", "version", "description"]

    missing = [field for field in required_fields if field not in spec_dict]
    if missing:
        raise IRValidatorException(f"Missing mandatory fields: {', '.join(missing)}")

    return spec_dict

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise IRValidatorException("yaml_file must be provided")

    try:
        with open(yaml_file, "r", encoding="utf-8") as f:
            try:
                data = yaml.safe_load(f)
            except Exception as e:
                raise IRValidatorException(f"Error parsing YAML file: {e}")
    except FileNotFoundError:
        raise IRValidatorException(f"YAML file not found: {yaml_file}")
    except Exception as e:
        raise IRValidatorException(f"Error opening YAML file: {e}")

    if data is None:
        data = {}
    if not isinstance(data, dict):
        raise IRValidatorException("YAML file must contain a mapping at the root")

    required = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dict")

    include = parser_dict.get("include")
    if include is None:
        return

    if not isinstance(include, dict):
        raise TypeError("The 'include' directive must be a dictionary")

    groups = parser_dict.get("groups")
    if groups is None:
        raise KeyError("Missing 'groups' key required for include resolution")
    if not isinstance(groups, dict):
        raise TypeError("The 'groups' key must map to a dictionary")

    for group_name

