def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    try:
        if not isinstance(command_name, str):
            raise TypeError("command_name must be a string")
        if not hasattr(self, "_command_options"):
            raise AttributeError("Command options not initialized")
        options = self._command_options.get(command_name)
        if options is None:
            raise ValueError(f"Unknown command: {command_name}")
        # Ensure we return a list
        if isinstance(options, (list, tuple)):
            return list(options)
        if isinstance(options, set):
            return list(options)
        if isinstance(options, dict):
            return list(options.keys())
        raise TypeError("Command options have unsupported type")
    except (TypeError, ValueError, AttributeError) as e:
        raise
    except Exception as e:
        raise RuntimeError("Failed to get parser option specs") from e

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Validate input arguments
    if not isinstance(command_name, str) or not command_name:
        raise ValueError("command_name must be a non-empty string")
    if not isinstance(argument_name, str) or not argument_name:
        raise ValueError("argument_name must be a non-empty string")

    # Retrieve the command object
    try:
        command = self.commands[command_name]
    except (KeyError, AttributeError):
        raise KeyError(f"Command '{command_name}' not found")

    # Retrieve the option specification
    try:
        options = getattr(command, "options", {})
        spec = options[argument_name]
    except (KeyError, TypeError):
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'")

    return spec

def get_silent_args(self, args):
    """
    list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    # Validate input
    if args is None:
        raise TypeError("args cannot be None")
    # Determine if args is a mapping (dict-like)
    silent_names = []
    try:
        if isinstance(args, dict):
            for name, value in args.items():
                if (isinstance(name, str) and name.startswith('_')) or value is None or value == '':
                    silent_names.append(name)
        else:
            # Assume iterable of items
            for item in args:
                # Tuple of (name, value)
                if isinstance(item, tuple) and len(item) == 2:
                    name, value = item
                    if (isinstance(name, str) and name.startswith('_')) or value is None or value == '':
                        silent_names.append(name)
                # Object with 'name' and 'value' attributes
                elif hasattr(item, 'name') and hasattr(item, 'value'):
                    name = getattr(item, 'name')
                    value = getattr(item, 'value')
                    if (isinstance(name, str) and name.startswith('_')) or value is None or value == '':
                        silent_names.append(name)
                # Simple string or other type treated as name with no value
                elif isinstance(item, str):
                    if item.startswith('_'):
                        silent_names.append(item)
                else:
                    # Unsupported item type; skip or raise
                    continue
    except Exception as exc:
        raise ValueError(f"Error processing args: {exc}") from exc
    return silent_names

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required = []
        if not isinstance(options_spec, (list, tuple)):
            raise TypeError("options_spec must be a list or tuple of option specs")
        if not isinstance(args, dict):
            raise TypeError("args must be a dictionary of received arguments")

        for opt in options_spec:
            # Skip if no name or no required_when
            name = opt.get("name")
            if not name:
                continue
            cond = opt.get("required_when")
            if cond is None:
                continue

            try:
                # Callable condition
                if callable(cond):
                    if cond(args):
                        required.append(name)
                    continue

                # Dictionary condition: key -> expected value
                if isinstance(cond, dict):
                    match = True
                    for key, expected in cond.items():
                        if args.get(key) != expected:
                            match = False
                            break
                    if match:
                        required.append(name)
                    continue

                # Boolean condition
                if isinstance(cond, bool):
                    if cond:
                        required.append(name)
                    continue

                # String condition: simple eval with args as locals
                if isinstance(cond, str):
                    # Only allow safe names from args
                    local_vars = {k: v for k, v in args.items()}
                    if eval(cond, {"__builtins__": {}}, local_vars):
                        required.append(name)
                    continue

                # Unsupported condition type: ignore
            except Exception:
                # If condition evaluation fails, ignore this option
                continue

        return required

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    :raises TypeError: If args is not a dict.
    :raises ValueError: If any argument's value length exceeds the specified maximum.
    """
    if args is None:
        raise ValueError("args cannot be None")
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")

    # Retrieve length specifications from the instance; default to empty dict if not present
    length_specs = getattr(self, "length_specs", {})
    if not isinstance(length_specs, dict):
        raise TypeError("length_specs attribute must be a dictionary if present")

    for key, value in args.items():
        # Skip keys that have no length specification
        if key not in length_specs:
            continue

        max_len = length_specs[key]
        if not isinstance(max_len, int) or max_len < 0:
            raise ValueError(f"Invalid maximum length for argument '{key}': {max_len}")

        # Determine the length of the value
        try:
            current_len = len(value)
        except TypeError:
            # If the value is not sized, convert to string and measure
            current_len = len(str(value))

        if current_len > max_len:
            raise ValueError(
                f"Argument '{key}' length {current_len} exceeds maximum allowed {max_len}"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the mapping of argument names to allowed choices
    choices_map = getattr(self, "_choices", None)
    if not isinstance(choices_map, dict):
        return

    # Convert args to a dictionary-like mapping if possible
    if isinstance(args, dict):
        arg_dict = args
    else:
        try:
            arg_dict = vars(args)
        except Exception:
            arg_dict = {}

    for arg_name, allowed in choices_map.items():
        if arg_name not in arg_dict:
            continue

        value = arg_dict[arg_name]
        if value is None:
            continue

        # If allowed is a callable, attempt to resolve it
        if callable(allowed):
            try:
                allowed = allowed()
            except Exception:
                continue

        if allowed is None:
            continue

        # Validate each element if the value is a sequence (but not a string)
        if isinstance(value, (list, tuple)):
            for v in value:
                if v not in allowed:
                    raise ValueError(
                        f"Invalid value '{v}' for argument '{arg_name}'. "
                        f"Allowed choices: {allowed}"
                    )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid value '{value}' for argument '{arg_name}'. "
                    f"Allowed choices: {allowed}"
                )

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.
    :param args: The received arguments.
    """
    try:
        # Ensure min and max attributes exist
        if not hasattr(self, 'min') or not hasattr(self, 'max'):
            raise AttributeError("Object must have 'min' and 'max' attributes")
        min_val = self.min
        max_val = self.max
        if min_val > max_val:
            raise ValueError(f"Invalid range: min ({min_val}) is greater than max ({max_val})")
        # Determine iterable of arguments
        if isinstance(args, dict):
            iterable = args.items()
        elif isinstance(args, (list, tuple)):
            iterable = enumerate(args)
        else:
            raise TypeError("args must be a dict, list, or tuple")
        for key, value in iterable:
            if not isinstance(value, (int, float)):
                raise TypeError(f"Argument {key} must be numeric, got {type(value).__name__}")
            if not (min_val <= value <= max_val):
                raise ValueError(f"Argument {key} with value {value} is out of bounds [{min_val}, {max_val}]")
    except Exception as exc:
        raise ValueError(f"Invalid arguments: {exc}") from exc

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: The updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict
    if not isinstance(extra_vars, (list, tuple)):
        raise TypeError("extra_vars must be a list or tuple of strings")
    for item in extra_vars:
        if not isinstance(item, str):
            continue
        if '=' not in item:
            continue
        key, value = item.split('=', 1)
        key = key.strip()
        if not key:
            continue
        value = value.strip()
        # Try to interpret common types
        if value.lower() == 'true':
            value = True
        elif value.lower() == 'false':
            value = False
        else:
            # Try integer conversion
            try:
                value = int(value)
            except ValueError:
                # Try float conversion
                try:
                    value = float(value)
                except ValueError:
                    # Keep as string
                    pass
        vars_dict[key] = value
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Basic argument validation
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string")
    if verbose is not None and not isinstance(verbose, int):
        raise TypeError("verbose must be an integer or None")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise TypeError("extra_vars must be a dict or None")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise TypeError("ansible_args must be a dict or None")

    import subprocess
    import json
    import sys
    import os

    # Resolve playbook path relative to the workspace if needed
    if not os.path.isabs(playbook_path):
        workspace_root = getattr(ir_workspace, "root", None)
        if workspace_root:
            playbook_path = os.path.join(workspace_root, playbook_path)
        playbook_path = os.path.abspath(playbook_path)

    cmd = ["ansible-playbook", playbook_path]

    # Add verbosity flag
    if verbose is not None:
        if verbose < 0 or verbose > 5:
            raise ValueError("verbose must be between 0 and 5")
        cmd.append("-" + "v" * verbose)

    # Add extra vars
    if extra_vars:
        cmd.extend(["--extra-vars", json.dumps(extra_vars)])

    # Add custom ansible arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    cmd.append(f"--{key}")
            elif isinstance(value, (list, tuple)):
                for v in value:
                    cmd.append(f"--{key}={v}")
            else:
                cmd.append(f"--{key}={value}")

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook command not found") from exc

    # Log output using the plugin's logger if available
    logger = getattr(ir_plugin, "log", None)
    if callable(logger):
        if result.stdout:
            logger(result.stdout)
        if result.stderr:
            logger(result.stderr)
    else:
        if result.stdout:
            print(result.stdout)
        if result.stderr:
            print(result.stderr, file=sys.stderr)

    # Raise an error if the playbook failed
    if result.returncode != 0:
        raise subprocess.CalledProcessError(
            result.returncode,
            cmd,
            output=result.stdout,
            stderr=result.stderr,
        )

    return result

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict in place.
        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of arguments
        :raises TypeError: if values_dict is not a dict
        """
        if not isinstance(values_dict, dict):
            raise TypeError("values_dict must be a dictionary")

        def _convert_value(val):
            """Attempt to convert a string value to bool, int, or float."""
            if not isinstance(val, str):
                return val
            lower_val = val.lower()
            if lower_val in ("true", "false"):
                return lower_val == "true"
            # Try integer conversion
            try:
                if val.startswith("-"):
                    if val[1:].isdigit():
                        return int(val)
                elif val.isdigit():
                    return int(val)
            except Exception:
                pass
            # Try float conversion
            try:
                float_val = float(val)
                return float_val
            except Exception:
                pass
            # Return original string if no conversion succeeded
            return val

        def _convert_dict(d):
            for key, val in list(d.items()):
                if isinstance(val, dict):
                    _convert_dict(val)
                elif isinstance(val, list):
                    new_list = []
                    for item in val:
                        new_list.append(_convert_value(item))
                    d[key] = new_list
                else:
                    d[key] = _convert_value(val)

        _convert_dict(values_dict)
        return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Validate plugin_dir
    if not isinstance(plugin_dir, (str, bytes, os.PathLike)):
        raise TypeError("plugin_dir must be a path-like object or string")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Directory not found: {plugin_dir}")

    # Determine spec file
    spec_path = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_path = candidate
            break
    if spec_path is None:
        raise FileNotFoundError("No plugin spec file (plugin.json, plugin.yaml, plugin.yml) found in directory")

    # Load spec
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            if spec_path.endswith(".json"):
                spec_data = json.load(f)
            else:
                # Try to import yaml
                try:
                    import yaml
                except ImportError as exc:
                    raise ImportError("PyYAML is required to parse YAML plugin specs") from exc
                spec_data = yaml.safe_load(f)
    except Exception as exc:
        raise ValueError(f"Failed to load plugin spec from {spec_path}: {exc}") from exc

    if not isinstance(spec_data, dict):
        raise ValueError("Plugin spec must be a dictionary at the top level")

    # Flatten dictionary
    def _flatten(d, parent_key=""):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            elif isinstance(v, list):
                for idx, item in enumerate(v):
                    list_key = f"{new_key}[{idx}]"
                    if isinstance(item, (dict, list)):
                        items.update(_flatten(item, list_key))
                    else:
                        items[list_key] = item
            else:
                items[new_key] = v
        return items

    flat_dict = _flatten(spec_data)
    return flat_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        import os
        if 'CONFIG_PATH' not in os.environ:
            default_path = os.path.join(os.getcwd(), 'config.yaml')
            os.environ['CONFIG_PATH'] = default_path
    except Exception as e:
        raise RuntimeError(f"Failed to inject config path: {e}") from e

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Validate input types
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    if root == "":
        raise ValueError("root cannot be an empty string")

    # Normalize root by stripping trailing path separators
    norm_root = root.rstrip('/\\')

    # If the path is exactly the root, return an empty string
    if path == norm_root or path == norm_root + '/' or path == norm_root + '\\':
        return ""

    # Check for root followed by a separator in the path
    if path.startswith(norm_root + '/'):
        return path[len(norm_root) + 1 :]
    if path.startswith(norm_root + '\\'):
        return path[len(norm_root) + 1 :]

    # If the path does not start with the root, raise an error
    raise ValueError(f"Path '{path}' does not start with root '{root}'")
